import math

def axis_velocity(previous_m, current_m, elapsed_s):
    values = (previous_m, current_m, elapsed_s)
    if not all(math.isfinite(value) for value in values):
        raise ValueError("finite inputs required")
    if elapsed_s <= 0:
        raise ValueError("elapsed_s must be positive")
    return (current_m - previous_m) / elapsed_s

assert math.isclose(axis_velocity(0.20, 0.26, 0.10), 0.60)
assert math.isclose(axis_velocity(0.26, 0.20, 0.10), -0.60)
for bad_dt in (0.0, -0.1, float("nan")):
    try:
        axis_velocity(0.20, 0.26, bad_dt)
    except ValueError:
        pass
    else:
        raise AssertionError("invalid time was accepted")
print("checked velocity examples passed")

