double norm3(const std::array<double, 3>& value) {
  for (double component : value) {
    if (!std::isfinite(component)) {
      throw std::invalid_argument("finite components required");
    }
  }
  return std::hypot(value[0], value[1], value[2]);
}

int main() {
  const std::array<double, 3> sample{3.0, 4.0, 0.0};
  const double magnitude = norm3(sample);
  if (std::abs(magnitude - 5.0) > 1e-12) return 1;
  std::cout << magnitude << std::endl;
  return 0;
}

