import math
import unittest

def fresh(now_s, stamp_s, limit_s):
    if not all(math.isfinite(v) for v in (now_s, stamp_s, limit_s)):
        return False
    if limit_s < 0:
        return False
    return 0 <= now_s - stamp_s <= limit_s

class FreshnessTests(unittest.TestCase):
    def test_current(self):
        self.assertTrue(fresh(10.0, 9.75, 0.5))
    def test_boundary(self):
        self.assertTrue(fresh(10.0, 9.5, 0.5))
    def test_stale(self):
        self.assertFalse(fresh(10.0, 9.0, 0.5))
    def test_future(self):
        self.assertFalse(fresh(10.0, 10.1, 0.5))
    def test_invalid(self):
        self.assertFalse(fresh(10.0, float("nan"), 0.5))

if __name__ == "__main__":
    unittest.main()

import math

def inspect(sample, now_s, active_indices, max_age_s=0.1):
    issues = []
    age = now_s - sample["received_monotonic_s"]
    if age < 0 or age > max_age_s:
        issues.append("INVALID_OR_STALE_ARRIVAL")
    motors = sample["motor_state"]
    for index in active_indices:
        if index >= len(motors):
            issues.append(f"MISSING_SLOT:{index}")
        elif not math.isfinite(motors[index]["q"]):
            issues.append(f"NONFINITE_POSITION:{index}")
    return issues

fixture = {"received_monotonic_s": 1.0,
           "motor_state": [{"q": 0.01*i} for i in range(35)]}
assert inspect(fixture, 1.02, range(29)) == []
fixture["motor_state"][20]["q"] = float("nan")
assert "NONFINITE_POSITION:20" in inspect(fixture, 1.02, range(29))
assert "INVALID_OR_STALE_ARRIVAL" in inspect(fixture, 1.2, range(29))
