def simulate(kp=4.0, kd=1.5, dt=0.01, duration=10.0):
    q, dq, peak, saturated = 0.0, 0.0, 0.0, 0
    target, inertia, damping, limit = 0.5, 1.0, 0.2, 1.0
    for _ in range(round(duration / dt)):
        requested = kp * (target - q) - kd * dq
        torque = max(-limit, min(limit, requested))
        saturated += abs(requested) > limit
        ddq = (torque - damping * dq) / inertia
        dq += ddq * dt
        q += dq * dt
        peak = max(peak, q)
    return {"final_error_rad": target-q, "peak_rad": peak,
            "saturated_steps": saturated}

for gains in [(4.0, 1.5), (4.0, 0.0), (8.0, 1.5)]:
    print(gains, simulate(*gains))

import math

L1, L2 = 0.4, 0.3

def fk(q1, q2):
    return (L1*math.cos(q1)+L2*math.cos(q1+q2),
            L1*math.sin(q1)+L2*math.sin(q1+q2))

def ik(x, y):
    c2 = (x*x+y*y-L1*L1-L2*L2)/(2*L1*L2)
    if not -1.0 <= c2 <= 1.0:
        raise ValueError("target outside ideal reachable annulus")
    solutions = []
    for q2 in (math.acos(c2), -math.acos(c2)):
        q1 = math.atan2(y, x)-math.atan2(L2*math.sin(q2), L1+L2*math.cos(q2))
        solutions.append((q1, q2))
    return solutions

for joints in ik(0.4, 0.2):
    point = fk(*joints)
    assert math.dist(point, (0.4, 0.2)) < 1e-12
    print(joints, point)
